"""Dependency metadata helpers."""

from __future__ import annotations

from typing import Dict, List, Optional

import pkg_resources


def dependency_report(names: list[str]) -> dict[str, str | None]:
    """Map each requested distribution name to its installed version, or None.

    Names are matched case-insensitively by the packaging metadata layer, while
    the returned mapping preserves each name exactly as provided.
    """
    report: dict[str, str | None] = {}
    for name in names:
        try:
            report[name] = pkg_resources.get_distribution(name).version
        except pkg_resources.DistributionNotFound:
            report[name] = None
    return report

"""Validation helper for sign-up payloads."""
from __future__ import annotations

from marshmallow import EXCLUDE, Schema, ValidationError, fields, validate, validates


class SignupSchema(Schema):
    class Meta:
        unknown = EXCLUDE

    username = fields.String(required=True)
    email = fields.Email(required=True)
    plan = fields.String(load_default="free", validate=validate.OneOf(["free", "pro", "team"]))
    age = fields.Integer(validate=validate.Range(min=16, max=120))

    @validates("username")
    def validate_username(self, value):
        if not value.isalnum():
            raise ValidationError("Username must be alphanumeric.")


class SignupError(ValueError):
    def __init__(self, messages):
        super().__init__("invalid signup data: %s" % (messages,))
        self.messages = messages


def validate_signup(data: dict) -> dict:
    """Validate and clean a sign-up payload.

    Required fields:
      - username: alphanumeric string
      - email: valid email address

    Optional fields:
      - plan: one of free, pro, team; defaults to free
      - age: integer between 16 and 120 inclusive

    Unknown keys are dropped.

    Returns the cleaned dict. On invalid input raises ValueError with a
    `messages` attribute mapping field names to lists of error messages.
    """
    try:
        return SignupSchema().load(data)
    except ValidationError as err:
        raise SignupError(err.messages) from None
